import{_ as l,l as i,o as e,c as s,v as o,p as n,x as t,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"布谷过滤器","description":"","frontmatter":{"title":"布谷过滤器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cuckoo-filter.md","filePath":"cs/cuckoo-filter.md","lastUpdated":1789023840000}'),p={name:"cs/cuckoo-filter.md"};function m(f,a,_,u,B,E){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="布谷过滤器" tabindex="-1">布谷过滤器 <a class="header-anchor" href="#布谷过滤器" aria-label="Permalink to &quot;布谷过滤器&quot;">​</a></h1><div class="epigraph"><p>不存键，只存指纹；每个指纹两个候选桶，插入像布谷散列那样踢。删除可以摘掉指纹，Bloom 做不到。</p><footer>—— 据 Fan, Andersen, Kaminsky and Mitzenmacher, Cuckoo Filter: Practically Better Than Bloom, CoNEXT 2014；Pagh and Rodler, Cuckoo Hashing 整理</footer></div><p><a href="/cs/hyperloglog">上一课</a> 不支持成员。<a href="/cs/bloom-filter">布隆</a> 假阳性、无删除（标准版）。<a href="/cs/robin-cuckoo">布谷散列</a> 存真键。本课不估基数。缺口是 cuckoo filter：桶里是指纹，用 <code>h1</code> 与 <code>h1 xor hash(fp)</code> 定位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>近似集：空间近 Bloom，但要删除、要查失败时仍紧凑。指纹 \\(\\mathrm{fp}(x)\\) 短，假阳性约桶负载与指纹位数决定。插入：两桶有空则放；否则踢走一个指纹到另一桶（由 fp 反推另一下标）。踢链过长则扩容或失败。缺口是<strong>用指纹的异或关系代替存键</strong>，使踢人仍能找到另一巢。</p><p><span class="marginnote">Fan et al., <em>CoNEXT</em>, 2014。半桶（bucket）存多个指纹，提高占用率。Pagh–Rodler 布谷给踢人算法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：检查两桶是否含 fp。删除：找到则删一个匹配指纹——可能误删同指纹的另一键，合同是近似。计数器 Bloom 可删但更费空间。</p>',8)),(e(),n(h,null,{default:t(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22x%22%5D%20--%3E%20FP%5B%22%E6%8C%87%E7%BA%B9%20fp%22%5D%0A%20%20FP%20--%3E%20B1%5B%22%E6%A1%B6%20h1(x)%22%5D%0A%20%20FP%20--%3E%20B2%5B%22%E6%A1%B6%20h1%20xor%20hash(fp)%22%5D%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%22%5D%20--%3E%20KICK%5B%22%E8%B8%A2%E6%8C%87%E7%BA%B9%E5%88%B0%E5%8F%A6%E4%B8%80%E6%A1%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与 Bloom：\\(k\\) 个独立位 vs 两桶指纹。布谷过滤器缓存局部性更好（查两桶），同空间下假阳性常更优（论文实验），本课用机制说话不抄表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>另一桶必须由当前桶与 fp 算出，故不能只存无法反推的索引。负载因子过高踢失败，要留空。假阴性：标准正确实现查找不应假阴；误删造成假阴，删除须应用层保证「曾插入」。</p><p>商过滤器下一课用商+余数紧排，另一套可删近似集。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给对抗构造去刷误删。不把 CoNEXT 图表当正文。精确字典请回完美散列或 HAMT。</p><p>后课默认：可删近似成员可用布谷过滤器。紧凑商+余数布局用商过滤器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>布谷过滤器：指纹 + 两巢踢人，可删。</li><li>假阳性由指纹长与负载决定。</li><li>下一课商过滤器换布局。</li><li>出处：Fan et al., <em>CoNEXT</em>, 2014；Pagh and Rodler。</li></ul>',9))])}const T=l(p,[["render",m]]);export{A as __pageData,T as default};
